ALTER TABLE match_participants ENABLE ROW LEVEL SECURITY;
ALTER TABLE match_scores ENABLE ROW LEVEL SECURITY;

changeSet.rollback:
ALTER TABLE matches DISABLE ROW LEVEL SECURITY;
ALTER TABLE match_participants DISABLE ROW LEVEL SECURITY;
ALTER TABLE match_scores DISABLE ROW LEVEL SECURITY;

changeSet.sql:
CREATE POLICY matches_select_participant ON matches
    FOR SELECT
    USING (fn_is_match_participant(id));

CREATE POLICY match_participants_select_participant ON match_participants
    FOR SELECT
    USING (fn_is_match_participant(match_id));

CREATE POLICY match_scores_select_participant ON match_scores
    FOR SELECT
    USING (fn_is_match_participant(match_id));

changeSet.rollback:
DROP POLICY IF EXISTS matches_select_participant ON matches;
DROP POLICY IF EXISTS match_participants_select_participant ON match_participants;
DROP POLICY IF EXISTS match_scores_select_participant ON match_scores;

changeSet.sql:
CREATE POLICY match_verifications_select_participant ON match_verifications
    FOR SELECT
    USING (fn_is_match_participant(match_id));

CREATE POLICY player_ratings_select_all ON player_ratings
    FOR SELECT
    USING (true);

CREATE POLICY rating_transactions_select_own ON rating_transactions
    FOR SELECT
    USING (player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid()));

