changeSet.sql:
CREATE POLICY notification_deliveries_select_own ON notification_deliveries
    FOR SELECT
    USING (
        notification_id IN (SELECT id FROM notifications WHERE user_id = auth.uid())
    );

ALTER TABLE events ENABLE ROW LEVEL SECURITY;
ALTER TABLE tournaments ENABLE ROW LEVEL SECURITY;
ALTER TABLE tournament_registrations ENABLE ROW LEVEL SECURITY;
ALTER TABLE bracket_matches ENABLE ROW LEVEL SECURITY;

changeSet.rollback:
ALTER TABLE events DISABLE ROW LEVEL SECURITY;
ALTER TABLE tournaments DISABLE ROW LEVEL SECURITY;
ALTER TABLE tournament_registrations DISABLE ROW LEVEL SECURITY;
ALTER TABLE bracket_matches DISABLE ROW LEVEL SECURITY;

changeSet.sql:
CREATE POLICY events_select_public ON events
    FOR SELECT
    USING (visibility = 'public' AND status != 'draft');

CREATE POLICY events_select_own ON events
    FOR SELECT
    USING (
        created_by_player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
    );

CREATE POLICY tournaments_select_visible ON tournaments
    FOR SELECT
    USING (
        event_id IN (
            SELECT id FROM events
            WHERE (visibility = 'public' AND status != 'draft')
               OR created_by_player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
        )
    );

CREATE POLICY tournament_registrations_select_own ON tournament_registrations
    FOR SELECT
    USING (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
        OR partner_player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
    );

CREATE POLICY bracket_matches_select_visible ON bracket_matches
    FOR SELECT
    USING (
        tournament_id IN (
            SELECT t.id FROM tournaments t
            JOIN events e ON t.event_id = e.id
            WHERE (e.visibility = 'public' AND e.status != 'draft')
               OR e.created_by_player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
        )
    );
